Q: Dart - Detect non-completing futures A: <blockquote>
<blockquote>
<p>HTTP connections not being closed down correctly.</p>
</blockquote>
</blockquote>
<p>It is not a good idea to deactivate such timers.<br />
The safest way is to let them do their thing.<br />
But let them do it in a <code>quiet zone</code>.</p>
<p>This is implemented in an elementary way.<br />
In the example below, this is achieved by using the <code>runAndDetach()</code> function.</p>
<p>It either returns a value (if it has time to do so) or returns an error (if this is a connection creation error) and <code>switches</code> the <code>socket zone</code> to <code>quiet</code> mode.<br />
In <code>quiet</code> mode, the socket can release all resources without any problems and may throws an exception, which is of no interest to the application.</p>
<p>However, this method requires intervention. Specifically, all connection-related operations must be canceled manually or using third-party functionality. These operations will not be interrupted, but simply stalled.<br />
In the example below, this is achieved by using the <code>runCancellable()</code> function.</p>
<pre class="lang-dart prettyprint-override"><code>import 'dart:async';

import 'package:defer/defer.dart';
import 'package:http/http.dart' as http;
import 'package:multitasking/multitasking.dart';

Future&lt;void&gt; main() async {
  final cts = CancellationTokenSource();
  final token = cts.token;
  final tasks = &lt;Task&lt;String&gt;&gt;[];
  final rss = &lt;String&gt;[
    'https://rss.nytimes.com/services/xml/rss/nyt/Sports.xml',
    'https://rss.nytimes.com/services/xml/rss/nyt/Science.xml',
    'https://rss.nytimes.com/services/xml/rss/nyt/Movies.xml',
    'https://rss.nytimes.com/services/xml/rss/nyt/Europe.xml',
    'https://rss.nytimes.com/services/xml/rss/nyt/Music.xml'
  ];

  final cancellationRequest = Completer&lt;void&gt;()
    // ignore: unawaited_futures
    ..future.then((_) {
      _message('Canceling');
      cts.cancel();
    });

  void cancel() {
    if (!cancellationRequest.isCompleted) {
      cancellationRequest.complete();
    }
  }

  for (var i = 0; i &lt; rss.length; i++) {
    final task = Task.run(() async {
      final uri = Uri.parse(rss[i]);
      final bytes = &lt;int&gt;[];
      _message('Fetching feed: $uri');

      token.throwIfCancelled();
      final client = http.Client();

      await runCancellable(token, client.close, () async {
        await defer(() async {
          client.close();
        }, () async {
          final response = await runAndDetach(() {
            return client.send(http.Request('GET', uri));
          });

          if (response.statusCode != 200) {
            throw StateError('Http error (${response.statusCode}): $uri');
          }

          final iterator = StreamIterator(response.stream);
          await runCancellable(token, iterator.cancel, () async {
            await defer(iterator.cancel, () async {
              while (await iterator.moveNext()) {
                bytes.addAll(iterator.current);
              }
            });
          });
        });
      });

      token.throwIfCancelled();

      // Simulate external cancellation request.
      // To initiate the cancellation of the remaining tasks
      cancel();

      final result = String.fromCharCodes(bytes);
      _message('Processing feed: $uri');
      await Future&lt;void&gt;.delayed(Duration(seconds: 1));
      return result;
    });

    tasks.add(task);
  }

  try {
    await Task.waitAll(tasks);
  } catch (e) {
    print(e);
  }

  for (final task in tasks) {
    print('-' * 40);
    print('${task.toString()}: ${task.state.name}');
    if (task.isCompleted) {
      final value = await task;
      final text = value;
      final length = text.length &lt; 80 ? text.length : 80;
      print('Data ${text.substring(0, length)}');
    } else {
      print('No data');
    }
  }
}

void _message(String text) {
  final task = Task.current.name ?? '${Task.current}';
  print('$task: $text');
}

</code></pre>
<p>Results:</p>
<pre class="lang-none prettyprint-override"><code>Task(0): Fetching feed: https://rss.nytimes.com/services/xml/rss/nyt/Sports.xml
Task(1): Fetching feed: https://rss.nytimes.com/services/xml/rss/nyt/Science.xml
Task(2): Fetching feed: https://rss.nytimes.com/services/xml/rss/nyt/Movies.xml
Task(3): Fetching feed: https://rss.nytimes.com/services/xml/rss/nyt/Europe.xml
